body:
## CODER 8 — unified diff part 1/2 (base `ea490b82`)

```diff
diff --git a/miniandroid/Makefile b/miniandroid/Makefile
index ca9c8cd..206b351 100755
--- a/miniandroid/Makefile
+++ b/miniandroid/Makefile
@@ -155,6 +155,18 @@ $(LAWS130_EXECUTABLE): $(CORE_OBJECTS) $(QUICKJS_OBJECTS) $(LAWS130_SOURCE)
 	@mkdir -p $(BUILDDIR)
 	$(CXX) $(CXXFLAGS) $(INCLUDES) $(JSON_INCLUDE) -o $@ $(LAWS130_SOURCE) $(CORE_OBJECTS) $(QUICKJS_OBJECTS) $(LIBS) $(FONTS_LIBS)

+# S163-CONC (CODER 8): independent base-concurrency harness -- 12 shared
+# scheduling/lifecycle/wait-notify/future verifications, 3-run determinism.
+S163_SOURCE = $(TESTDIR)/s163_concurrency_harness.cpp
+S163_EXECUTABLE = $(BUILDDIR)/s163_concurrency_harness
+
+s163_harness: $(S163_EXECUTABLE)
+	./$(S163_EXECUTABLE); echo "exit=$$?"
+
+$(S163_EXECUTABLE): $(CORE_OBJECTS) $(QUICKJS_OBJECTS) $(THUNK_OBJECT) $(BUILDDIR)/jni/bionic_compat.o $(S163_SOURCE)
+	@mkdir -p $(BUILDDIR)
+	$(CXX) $(CXXFLAGS) $(INCLUDES) $(JSON_INCLUDE) -rdynamic -o $@ $(S163_SOURCE) $(CORE_OBJECTS) $(QUICKJS_OBJECTS) $(THUNK_OBJECT) $(BUILDDIR)/jni/bionic_compat.o $(LIBS) $(FONTS_LIBS)
+
 test: $(TEST_EXECUTABLE)
 	./$(TEST_EXECUTABLE)

diff --git a/miniandroid/src/dex/dalvik_engine.cpp b/miniandroid/src/dex/dalvik_engine.cpp
index 8c622c9..8597803 100755
--- a/miniandroid/src/dex/dalvik_engine.cpp
+++ b/miniandroid/src/dex/dalvik_engine.cpp
@@ -39,6 +39,7 @@
 #include "../framework/shadow_registry.h"
 #include <functional>
 #include "../framework/android_shadows.h"
+#include "../framework/executor_shadow.h"  // S163-CONC: Future law
 #include "../webview/webview_engine.h"
 #include "../framework/choreographer_shadow.h"  // R-NEW-345 park-drain: vsync during park
 #include "../framework/dialog_shadow.h"
@@ -31948,6 +31949,13 @@ void DalvikExecutionEngine::run_thread_start_body(uint32_t thread_oid,
     } else if (ts_shadow && thread_oid != 0) {
         // Body completed (loop exit / return) — never re-drain it.
         ts_shadow->clear_thread_yielded(thread_oid);
+        // S163-CONC (CODER 8) TERMINATION LAW: a body that ran to completion
+        // (returned or loop-exited without parking) has TERMINATED — JDK
+        // Thread state law. isAlive() flips false; join() on this target
+        // returns. Was: no state existed, isAlive() answered true forever.
+        ts_shadow->mark_thread_terminated(thread_oid);
+        std::cerr << "[THREAD-LIFE] thread o" << thread_oid
+                  << " body completed → TERMINATED" << std::endl;
     }
     std::cerr << "[THREAD-START] drained oid=" << run_oid << " cls=" << rcls
               << (target_oid == thread_oid && thread_oid != 0
@@ -31958,6 +31966,73 @@ void DalvikExecutionEngine::run_thread_start_body(uint32_t thread_oid,
               << std::endl;
 }

+// ═══════════════════════════════════════════════════════════════════════════
+// S163-CONC (CODER 8) — FUTURETASK RUN/COMPLETE LAW.
+//
+// Runs the REAL task body behind a FutureTask and flips the future state:
+//   * cancelled future → silent no-op (OpenJDK FutureTask.run: state guard
+//     handles/rans only NEW→...; a cancelled task never runs its body),
+//   * Runnable task  → REAL DEX run(),
+//   * Callable-shaped task (run() absent) → REAL DEX call() with the REAL
+//     return value captured into the COMPLETED future record,
+//   * thrown body → EXCEPTION state (uncaught-in-flight delta is the
+//     engine's exception-honesty signal, F-016 family).
+// Returns true when a body actually executed.
+// ═══════════════════════════════════════════════════════════════════════════
+bool DalvikExecutionEngine::run_and_complete_future(uint32_t future_oid) {
+    if (shadow_registry_ == nullptr) return false;
+    auto* ex = shadow_registry_->find_as<framework::ExecutorShadow>();
+    if (ex == nullptr) return false;
+    const auto* rec = ex->future_record(future_oid);
+    if (rec == nullptr) return false;
+    if (rec->state == framework::ExecutorShadow::kFutureCancelled) {
+        std::cerr << "[EXECUTOR][FUTURE] run o" << future_oid
+                  << " skipped (CANCELLED — OpenJDK run() state guard)"
+                  << std::endl;
+        return false;
+    }
+    if (rec->state != framework::ExecutorShadow::kFuturePending) return false;
+    uint32_t task = rec->task_oid;
+    if (task == 0 || !heap_.has_object(task)) {
+        // Executor-completed without a DEX body (empty task): complete with
+        // the recorded payload or null — never leave the future pending.
+        ex->complete_task(task, false, 0);
+        return false;
+    }
+    std::string tcls = "Ljava/lang/Object;";
+    if (const auto* tobj = heap_.get(task))
+        if (!tobj->class_descriptor.empty()) tcls = tobj->class_descriptor;
+    DalvikValue self_t = DalvikValue::make_object(task, tcls);
+    DalvikValue task_ret;
+    DalvikExecutionResult task_res;
+    std::vector<DalvikValue> task_args{self_t};
+    size_t uncaught_before = task_res.uncaught_in_flight_count;
+    bool ran = try_recursive_invoke(tcls, "run", task_args, task_ret,
+                                    task_res, "()V");
+    bool has_result = false;
+    if (!ran) {
+        // Callable-shaped task: REAL DEX call() with the REAL return value.
+        DalvikExecutionResult call_res;
+        ran = try_recursive_invoke(tcls, "call", task_args, task_ret,
+                                   call_res,
+                                   "(Ljava/lang/Object;)Ljava/lang/Object;");
+        task_res.uncaught_in_flight_count += call_res.uncaught_in_flight_count;
+        has_result = ran && task_ret.type == DalvikType::OBJECT_REF;
+    }
+    bool threw = task_res.uncaught_in_flight_count > uncaught_before;
+    std::string rdesc;
+    if (has_result && heap_.has_object(task_ret.object_id)) {
+        if (const auto* ro = heap_.get(task_ret.object_id))
+            rdesc = ro->class_descriptor;
+    }
+    ex->complete_task(task, threw, 0, has_result,
+                      has_result ? task_ret.object_id : 0, rdesc);
+    std::cerr << "[EXECUTOR][FUTURE] ran task o" << task << " cls=" << tcls
+              << " → " << (ran ? "REAL DEX body executed" : "no body found")
+              << (threw ? " (EXCEPTION)" : "") << std::endl;
+    return ran;
+}
+
 // R-NEW-345: park = deterministic yield point. See the law note at the
 // LockSupport case in bridge_to_api. Bounded rounds; reentrancy-guarded so
 // a park reached THROUGH drained work yields instead of recursing.
@@ -32027,6 +32102,20 @@ uint64_t DalvikExecutionEngine::drain_park_queues_bounded(const char* reason) {
                     try_recursive_invoke(rcls, "run", run_args, ret, res, "()V");
                     if (bound_mq_identity)
                         ts->set_active_drained_thread(saved_mq_identity);
+                    // S163-CONC (CODER 8) FUTURE COMPLETION HOOK: the drained
+                    // entry was a submitted task — flip its future to
+                    // COMPLETED/EXCEPTION (F-016 uncaught delta is the throw
+                    // signal). When run() was not found and the entry IS a
+                    // directly-enqueued FutureTask, run its law body.
+                    if (auto* ex_hook =
+                            shadow_registry_->find_as<framework::ExecutorShadow>()) {
+                        if (ex_hook->future_of_task(rid) != 0) {
+                            ex_hook->complete_task(
+                                rid, res.uncaught_in_flight_count > 0, 0);
+                        } else if (ex_hook->is_future(rid)) {
+                            run_and_complete_future(rid);
+                        }
+                    }
                 }
                 work_units += drained.size();
             }
@@ -34274,6 +34363,232 @@ bool DalvikExecutionEngine::bridge_to_api(const std::string& class_name,
             return true;
         }
     }
+    // ══════════════════════════════════════════════════════════════════════
+    // S163-CONC (CODER 8) — OBJECT MONITOR CONDITION LAW:
+    // Object.wait() / Object.notify() / Object.notifyAll().
+    //
+    // These are final instance methods on java.lang.Object — every heap
+    // object is a monitor. The engine previously had NO implementation
+    // anywhere: a wait() call fell through to the unimplemented-API path and
+    // either no-op'd silently (wait returns immediately → producer/consumer
+    // loops spin at full interpreter speed and observe garbage state) or
+    // loud-stubbed. That is the shared root of every intrinsic-condition-
+    // queue app pattern.
+    //
+    // Law (JLS 17.2 + OpenJDK Object.java, deterministic-serialized model):
+    //   * notify()/notifyAll(): release one/all waiters on THIS monitor's
+    //     wait set (ThreadShadow::notify_monitor). Released waiters wake at
+    //     the next scheduler boundary. No waiters → no-op (legal).
+    //   * wait(): inside a drained body (F-110b park depth >= 1) the calling
+    //     thread registers on the monitor's wait set and parks EXACTLY like
+    //     Thread.sleep parks — the frame chain unwinds at the wait site and
+    //     the body re-drains when released (notify/notifyAll/interrupt) or
+    //     when the timeout expires (wake = now + timeout; wait(0) = wait
+    //     forever, wake = INT64_MAX). On body re-entry the wait site
+    //     consumes the release record: a notified/expired wait returns
+    //     normally; an interrupted wait throws InterruptedException.
+    //   * wait() on the MAIN context (no drained body to park): documented
+    //     boundary — advance the ONE virtual clock by the timeout (bounded
+    //     block, same law family as main-context Thread.sleep) and log
+    //     loudly; wait(0) on main is logged as a would-hang-forever law
+    //     violation and returns (the engine cannot progress-hang).
+    //   * Monitor OWNERSHIP is not enforced (MONITOR_ENTER/EXIT are the
+    //     documented no-op single-thread law — an uncontended monitor can
+    //     never be held by someone else here, so the IllegalMonitorState
+    //     check would throw on LEGAL code; recorded as a boundary, never
+    //     silent).
+    // ══════════════════════════════════════════════════════════════════════
+    if ((method == "wait" || method == "notify" || method == "notifyAll") &&
+        !args.empty() && args[0].type == DalvikType::OBJECT_REF &&
+        shadow_registry_ != nullptr) {
+        auto* ts_mon = shadow_registry_->find_as<framework::ThreadShadow>();
+        auto* hs_mon = shadow_registry_->find_as<framework::HandlerShadow>();
+        uint32_t monitor_oid = args[0].object_id;
+        if (ts_mon != nullptr) {
+            if (method == "notify" || method == "notifyAll") {
+                size_t woken = ts_mon->notify_monitor(monitor_oid,
+                                                      method == "notifyAll");
+                static thread_local uint64_t ntf_log = 0;
+                if (ntf_log < 24) {
+                    ++ntf_log;
+                    std::cerr << "[MONITOR] Object." << method
+                              << " monitor=o" << monitor_oid << " → woken="
+                              << woken << " waiter(s)" << std::endl;
+                }
+                status = ApiCallTrace::Status::IMPLEMENTED;
+                result = DalvikValue::make_void();
+                return true;
+            }
+            // ── wait ──
+            int64_t timeout_ms = 0;
+            if (args.size() >= 2) {
+                timeout_ms = args[1].type == DalvikType::INT64
+                                 ? args[1].long_val
+                                 : static_cast<int64_t>(args[1].int_val);
+            }
+            uint32_t self = ts_mon->current_thread_id();
+            // Re-entry law: a parked body re-drains HERE first — consume the
+            // release record; interrupted waiters surface InterruptedException
+            // exactly like an AOSP wait would.
+            bool was_interrupted = false;
+            if (ts_mon->consume_wait_resume(self, monitor_oid,
+                                            &was_interrupted)) {
+                if (was_interrupted) {
+                    std::cerr << "[MONITOR] wait monitor=o" << monitor_oid
+                              << " self=o" << self
+                              << " → InterruptedException (interrupt-while-"
+                              << "waiting law)" << std::endl;
+                    throw_deferred("Ljava/lang/InterruptedException;",
+                                   "wait() interrupted", "S163-WAIT");
+                    result = DalvikValue::make_void();
+                    return true;
+                }
+                static thread_local uint64_t wr_log = 0;
+                if (wr_log < 24) {
+                    ++wr_log;
+                    std::cerr << "[MONITOR] wait monitor=o" << monitor_oid
+                              << " self=o" << self
+                              << " resumed (notified/timeout)" << std::endl;
+                }
+                status = ApiCallTrace::Status::IMPLEMENTED;
+                result = DalvikValue::make_void();
+                return true;
+            }
+            int64_t now_mon = hs_mon ? hs_mon->virtual_now_ms() : 0;
+            int64_t wake_mon = (timeout_ms > 0)
+                                   ? now_mon + timeout_ms
+                                   : INT64_MAX;  // wait(0) = wait forever
+            ts_mon->register_wait(self, monitor_oid, wake_mon);
+            static thread_local uint64_t wt_log = 0;
+            if (wt_log < 24) {
+                ++wt_log;
+                std::cerr << "[MONITOR] wait monitor=o" << monitor_oid
+                          << " self=o" << self << " timeout=" << timeout_ms
+                          << "ms wake="
+                          << (wake_mon == INT64_MAX ? std::string("never")
+                                                    : std::to_string(wake_mon))
+                          << " (park depth=" << park_drain_last_depth_ << ")"
+                          << std::endl;
+            }
+            if (park_drain_last_depth_ >= 1) {
+                // Same park mechanism as the F-110b sleep yield: unwind the
+                // drained body at this call site; the boundary drain re-runs
+                // the body when the wait is released or times out.
+                park_yield_pending_ = true;
+                park_yield_wake_at_ = wake_mon;
+            } else {
+                // MAIN-context boundary (documented): a bounded wait advances
+                // the virtual clock (the block time elapses); an unbounded
+                // wait(0) cannot progress-hang the serialized engine.
+                if (timeout_ms > 0 && hs_mon)
+                    hs_mon->advance_virtual(timeout_ms);
+                ts_mon->consume_wait_resume(self, monitor_oid,
+                                            &was_interrupted);
+                std::cerr << "[MONITOR][BOUNDARY] wait(" << timeout_ms
+                          << "ms) on main context monitor=o" << monitor_oid
+                          << (timeout_ms > 0
+                                  ? " — virtual clock advanced by the block"
+                                  : " — wait(0) on main would hang forever;"
+                                    " documented serialized boundary")
+                          << std::endl;
+            }
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            result = DalvikValue::make_void();
+            return true;
+        }
+    }
+    // ══════════════════════════════════════════════════════════════════════
+    // S163-CONC (CODER 8) — THREAD.JOIN DRIVE LAW.
+    //
+    // join() was a silent no-op: it returned while the target body had not
+    // necessarily run to completion, so every "worker + join + read result"
+    // shape observed stale state. JDK law: join() blocks the CALLER until
+    // the target terminates. Deterministic counterpart: drive ONLY the
+    // target's scheduler state to termination — run its pending start body,
+    // advance the clock to its parked wake and re-drain — without executing
+    // unrelated scheduler work. join(timeout) bounds the total clock
+    // advance by the timeout (JDK: join(ms) returns after the block time
+    // regardless of termination).
+    // ══════════════════════════════════════════════════════════════════════
+    if (is_thread_receiver(class_name) && method == "join" &&
+        !args.empty() && args[0].type == DalvikType::OBJECT_REF &&
+        shadow_registry_ != nullptr) {
+        auto* ts_join = shadow_registry_->find_as<framework::ThreadShadow>();
+        auto* hs_join = shadow_registry_->find_as<framework::HandlerShadow>();
+        uint32_t target = args[0].object_id;
+        if (ts_join != nullptr && target != 0) {
+            bool timed = false;
+            int64_t join_timeout = 0;
+            if (args.size() >= 2) {
+                timed = true;
+                join_timeout = args[1].type == DalvikType::INT64
+                                   ? args[1].long_val
+                                   : static_cast<int64_t>(args[1].int_val);
+            }
+            int64_t deadline = INT64_MAX;
+            if (timed && join_timeout > 0 && hs_join)
+                deadline = hs_join->virtual_now_ms() + join_timeout;
+            int rounds = 0;
+            bool reached_termination = false;
+            while (ts_join->is_thread_alive(target) ||
+                   ts_join->has_pending_start_for(target)) {
+                bool progressed = false;
+                uint32_t r_oid = 0;
+                if (ts_join->consume_pending_start_for(target, r_oid)) {
+                    run_thread_start_body(target, r_oid);
+                    progressed = true;
+                }
+                int64_t now_join =
+                    hs_join ? hs_join->virtual_now_ms() : INT64_MAX;
+                uint32_t yr = 0;
+                if (ts_join->take_due_yielded_for(target, now_join, yr)) {
+                    run_thread_start_body(target, yr);
+                    progressed = true;
+                } else if (ts_join->is_thread_alive(target)) {
+                    int64_t wake = ts_join->next_wake_for(target);
+                    if (wake != INT64_MAX && hs_join) {
+                        // Deterministic block time: advance to the parked
+                        // wake (bounded by the join deadline) and re-drain.
+                        int64_t cap = (deadline < wake) ? deadline : wake;
+                        if (cap > now_join) hs_join->advance_virtual(cap - now_join);
+                        progressed = true;
+                    }
+                }
+                if (reached_termination) break;
+                if (!ts_join->is_thread_alive(target) &&
+                    !ts_join->has_pending_start_for(target)) {
+                    reached_termination = true;
+                    break;
+                }
+                if (!progressed) break;  // nothing schedulable — stop honestly
+                if (++rounds > 64) {
+                    std::cerr << "[THREAD-JOIN][BOUNDARY] join target=o"
+                              << target << " did not terminate after 64 "
+                              << "scheduler rounds — returning honestly "
+                              << "(non-terminating body)" << std::endl;
+                    break;
+                }
+                if (timed && hs_join &&
+                    hs_join->virtual_now_ms() >= deadline)
+                    break;
+            }
+            static thread_local uint64_t join_log = 0;
+            if (join_log < 24) {
+                ++join_log;
+                std::cerr << "[THREAD-JOIN] target=o" << target << " rounds="
+                          << rounds << " terminated="
+                          << (ts_join->thread_state(target) ==
+                                      framework::ThreadShadow::ThreadState::
+                                          TERMINATED
+                                  ? "true"
+                                  : "false")
+                          << std::endl;
+            }
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            result = DalvikValue::make_void();
+            return true;
+        }
+    }
     // R-NEW-345 THREAD-START SELF-RUN DRAIN (generic law). When a Thread
     // subclass (kotlinx scheduler Worker, OkHttp/Looper threads — no
     // Runnable ctor target recorded) starts, ThreadShadow queues a SELF-run
@@ -34306,6 +34621,24 @@ bool DalvikExecutionEngine::bridge_to_api(const std::string& class_name,
     // suspension.
     if (is_thread_receiver(class_name) && method == "sleep" &&
         shadow_registry_ != nullptr) {
+        // S163-CONC (CODER 8) INTERRUPT-SLEEP LAW (JDK Thread.sleep): if the
+        // CURRENT thread's interrupt status is set, sleep clears it and
+        // throws InterruptedException IMMEDIATELY — it neither sleeps nor
+        // parks. Was: the flag was unobservable (interrupt was a no-op).
+        if (auto* ts_slp =
+                shadow_registry_->find_as<framework::ThreadShadow>()) {
+            uint32_t self_slp = ts_slp->current_thread_id();
+            if (ts_slp->consume_interrupted(self_slp)) {
+                std::cerr << "[THREAD-SLEEP] self=o" << self_slp
+                          << " interrupted status set → InterruptedException"
+                          << " (JDK sleep law)" << std::endl;
+                throw_deferred("Ljava/lang/InterruptedException;",
+                               "sleep interrupted", "S163-SLEEP");
+                status = ApiCallTrace::Status::IMPLEMENTED;
+                result = DalvikValue::make_void();
+                return true;
+            }
+        }
         // F-150: receiver class resolved through the superclass chain —
         // javac emits the SUBCLASS descriptor for unqualified Thread.sleep
         // inside Thread subclasses (snake GameMainThread ground truth).
@@ -51250,6 +51583,88 @@ bool DalvikExecutionEngine::bridge_to_api(const std::string& class_name,
     // provider-install window. Skip the shadow claim for this exact
     // (receiver-family, method) pair and fall through to the law.
     // ────────────────────────────────────────────────────────────────────
+    // ══════════════════════════════════════════════════════════════════════
+    // S163-CONC (CODER 8) — FUTURE.GET LAW (OpenJDK FutureTask.get).
+    //
+    // Reached only when the receiver maps to a REGISTERED future record —
+    // every other `get` receiver (ArrayList.get, Bundle.get, ...) falls
+    // through untouched. States:
+    //   * COMPLETED → the REAL completed value (Callable return or the
+    //     submit(Runnable, result) payload); no result → null.
+    //   * EXCEPTION → ExecutionException (documented: the cause chain is
+    //     carried in the message; a wrapped cause object is a later wave).
+    //   * CANCELLED → CancellationException.
+    //   * PENDING → deterministic completion drive: the queued entry is
+    //     removed by its token and the task body runs NOW (the serialized
+    //     counterpart of "the worker finishes the task before the blocked
+    //     get() returns") — REAL DEX, no fake result.
+    // ══════════════════════════════════════════════════════════════════════
+    if (method == "get" && !args.empty() &&
+        args[0].type == DalvikType::OBJECT_REF && shadow_registry_ != nullptr) {
+        if (auto* ex_get =
+                shadow_registry_->find_as<framework::ExecutorShadow>()) {
+            uint32_t fut = args[0].object_id;
+            if (ex_get->is_future(fut)) {
+                const auto* rec_get = ex_get->future_record(fut);
+                if (rec_get != nullptr) {
+                    if (rec_get->state ==
+                        framework::ExecutorShadow::kFutureCancelled) {
+                        std::cerr << "[EXECUTOR][FUTURE] get o" << fut
+                                  << " → CancellationException" << std::endl;
+                        throw_deferred(
+                            "Ljava/util/concurrent/CancellationException;",
+                            "Task was cancelled", "S163-FGET");
+                        result = DalvikValue::make_void();
+                        return true;
+                    }
+                    if (rec_get->state ==
+                        framework::ExecutorShadow::kFutureException) {
+                        std::cerr << "[EXECUTOR][FUTURE] get o" << fut
+                                  << " → ExecutionException" << std::endl;
+                        throw_deferred(
+                            "Ljava/util/concurrent/ExecutionException;",
+                            "Task threw an exception", "S163-FGET");
+                        result = DalvikValue::make_void();
+                        return true;
+                    }
+                    if (rec_get->state ==
+                        framework::ExecutorShadow::kFuturePending) {
+                        if (auto* hs_get =
+                                shadow_registry_->find_as<
+                                    framework::HandlerShadow>()) {
+                            size_t removed =
+                                hs_get->remove_by_token(fut);
+                            if (removed > 0)
+                                std::cerr << "[EXECUTOR][FUTURE] get o"
+                                          << fut << " drove its queued task "
+                                          << "to completion (removed "
+                                          << removed << " queue entry)"
+                                          << std::endl;
+                        }
+                        run_and_complete_future(fut);
+                        rec_get = ex_get->future_record(fut);
+                    }
+                    if (rec_get != nullptr &&
+                        rec_get->state ==
+                            framework::ExecutorShadow::kFutureCompleted) {
+                        if (rec_get->has_result && rec_get->result_oid != 0) {
+                            std::cerr << "[EXECUTOR][FUTURE] get o" << fut
+                                      << " → REAL result obj="
+                                      << rec_get->result_oid << " ("
+                                      << rec_get->result_desc << ")"
+                                      << std::endl;
+                            result = DalvikValue::make_object(
+                                rec_get->result_oid, rec_get->result_desc);
+                        } else {
+                            result = DalvikValue::make_null();
+                        }
+                        status = ApiCallTrace::Status::IMPLEMENTED;
+                        return true;
+                    }
+                }
+            }
+        }
+    }
     const bool provider_ctx366 =
