+    ex->complete_task(task, /*threw=*/false, 0);
+    rec = ex->future_record(fut.object_id);
+    check(rec && rec->state == ExecutorShadow::kFutureCompleted,
+          "drain hook flipped PENDING → COMPLETED");
+    ev(ts, hs, "TEST09 drain hook → COMPLETED");
+}
