+uint32_t ExecutorShadow::create_future(uint32_t task_oid, bool is_callable) {
+    if (!heap_) return 0;
+    uint32_t fid = heap_->allocate("Ljava/util/concurrent/FutureTask;");
+    FutureRecord& rec = futures_[fid];
+    rec.state = kFuturePending;
+    rec.task_oid = task_oid;
+    rec.is_callable = is_callable;
+    if (task_oid) future_of_task_[task_oid] = fid;
+    return fid;
+}
