+void ExecutorShadow::register_future_object(uint32_t future_oid,
+                                            uint32_t task_oid, bool is_callable,
+                                            uint32_t initial_result_oid,
+                                            const std::string& init_desc) {
+    if (!future_oid) return;
+    FutureRecord& rec = futures_[future_oid];
+    rec.state = kFuturePending;
+    rec.task_oid = task_oid;
+    rec.is_callable = is_callable;
+    if (task_oid) future_of_task_[task_oid] = future_oid;
+    if (initial_result_oid != 0) {
+        rec.has_result = true;
+        rec.result_oid = initial_result_oid;
+        rec.result_desc = init_desc;
+    }
+}
