+uint32_t ExecutorShadow::complete_task(uint32_t task_oid, bool threw,
+                                       uint32_t exc_oid, bool has_result,
+                                       uint32_t result_oid,
+                                       const std::string& result_desc) {
+    // S166-CONC: a drained task is no longer pending on its executor.
+    note_task_drained(task_oid);
+    // S173-CONC (wave 4): the REAL completed-task ledger (JDK
+    // getCompletedTaskCount contract — every task that FINISHED its run,
+    // whether or not it carried a Future).
+    auto tex = task_executor_.find(task_oid);
+    if (tex != task_executor_.end()) {
+        auto est = executors_.find(tex->second);
+        if (est != executors_.end()) est->second.tasks_completed++;
+        task_executor_.erase(tex);
+    }
+    auto it = future_of_task_.find(task_oid);
+    if (it == future_of_task_.end()) return 0;
+    uint32_t fid = it->second;
+    future_of_task_.erase(it);
+    auto fit = futures_.find(fid);
+    if (fit == futures_.end()) return 0;
+    FutureRecord& rec = fit->second;
+    if (rec.state != kFuturePending) return fid;  // cancelled: no flip
+    if (threw) {
+        rec.state = kFutureException;
+        rec.exc_oid = exc_oid;
+    } else {
+        rec.state = kFutureCompleted;
+        if (has_result) {
+            rec.has_result = true;
+            rec.result_oid = result_oid;
+            rec.result_desc = result_desc;
+        }
+    }
+    std::cerr << "[EXECUTOR][FUTURE] task o" << task_oid << " → future o"
+              << fid << " state="
+              << (threw ? "EXCEPTION"
+                        : (rec.state == kFutureCompleted ? "COMPLETED"
+                                                          : "PENDING"))
+              << std::endl;
+    // S174-CONC (CODER 8, wave 5): the ExecutorCompletionService hook —
+    // a future that belongs to an ECS joins ITS completion ledger in the
+    // order THIS hook runs (the JDK QueueingFuture.done() law: the
+    // completion queue receives the future in COMPLETION order, not
+    // submission order).
+    auto eit = ecs_of_future_.find(fid);
+    if (eit != ecs_of_future_.end()) {
+        auto sit = ecs_states_.find(eit->second);
+        if (sit != ecs_states_.end()) {
+            sit->second.completion_order.push_back(fid);
+            std::cerr << "[EXECUTOR][ECS] future o" << fid
+                      << " → completion queue of ECS o" << eit->second
+                      << " (depth=" << sit->second.completion_order.size()
+                      << ")" << std::endl;
+        }
+    }
+    return fid;
+}
