+void ExecutorShadow::note_task_enqueued(uint32_t executor_oid,
+                                        uint32_t task_oid) {
+    if (!executor_oid || !task_oid) return;
+    auto& v = pending_tasks_[executor_oid];
+    for (uint32_t t : v)
+        if (t == task_oid) return;  // already tracked
+    v.push_back(task_oid);
+    // S173-CONC: ownership ledger for the completed-task counter.
+    task_executor_[task_oid] = executor_oid;
+}
