+void ExecutorShadow::note_task_drained(uint32_t task_oid) {
+    if (!task_oid) return;
+    for (auto& [exec, v] : pending_tasks_) {
+        auto it = std::find(v.begin(), v.end(), task_oid);
+        if (it != v.end()) {
+            v.erase(it);
+            std::cerr << "[EXECUTOR][LIFE] task o" << task_oid
+                      << " drained — pending for executor o" << exec << " = "
+                      << v.size() << std::endl;
+            return;
+        }
+    }
+}
