+int64_t ExecutorShadow::timeunit_to_ms(uint32_t unit_oid,
+                                       int64_t value) const {
+    int32_t ordinal = 2;  // MILLISECONDS default
+    if (unit_oid && heap_ &&
+        heap_->get_object_int_field(unit_oid, "ordinal", ordinal)) {
+        // ordinal read succeeded
+    } else if (unit_oid) {
+        std::cerr << "[EXECUTOR][SCHED][BOUNDARY] TimeUnit arg o" << unit_oid
+                  << " has no ordinal — assuming MILLISECONDS" << std::endl;
+    }
+    switch (ordinal) {
+        case 0: return value / 1000000LL;  // NANOSECONDS
+        case 1: return value / 1000LL;     // MICROSECONDS
+        case 2: return value;              // MILLISECONDS
+        case 3: return value * 1000LL;     // SECONDS
+        case 4: return value * 60000LL;    // MINUTES
+        case 5: return value * 3600000LL;  // HOURS
+        case 6: return value * 86400000LL; // DAYS
+        default:
+            std::cerr << "[EXECUTOR][SCHED][BOUNDARY] unknown TimeUnit "
+                      << "ordinal " << ordinal << " — assuming MILLISECONDS"
+                      << std::endl;
+            return value;
+    }
+}
