+std::vector<uint32_t> ExecutorShadow::shutdown_now(uint32_t executor_oid) {
+    std::vector<uint32_t> purged;
+    auto it = pending_tasks_.find(executor_oid);
+    if (it == pending_tasks_.end()) return purged;
+    if (auto* hs = registry_ ? registry_->find_as<HandlerShadow>() : nullptr) {
+        for (uint32_t task_oid : it->second) {
+            // Purge the queued entry and flip the future CANCELLED — a
+            // shutdownNow task NEVER runs (JDK law). execute() tasks ride
+            // the queue with token 0 (remove by RUNNABLE id); submitted
+            // futures ride token == future oid (remove by token).
+            hs->remove_callbacks(task_oid);
+            auto fot = future_of_task_.find(task_oid);
+            if (fot != future_of_task_.end()) {
+                hs->remove_by_token(fot->second);
+                auto fit = futures_.find(fot->second);
+                if (fit != futures_.end() &&
+                    fit->second.state == kFuturePending)
+                    fit->second.state = kFutureCancelled;
+                future_of_task_.erase(fot);
+            }
+            purged.push_back(task_oid);
+        }
+    }
+    std::cerr << "[EXECUTOR] shutdownNow executor o" << executor_oid
+              << " — purged " << purged.size() << " never-run task(s)"
+              << std::endl;
+    it->second.clear();
+    return purged;
+}
