+bool ExecutorShadow::cancel_future(uint32_t future_oid) {
+    auto it = futures_.find(future_oid);
+    if (it == futures_.end()) return false;
+    if (it->second.state != kFuturePending) {
+        std::cerr << "[EXECUTOR][FUTURE] cancel o" << future_oid
+                  << " -> false (state=" << it->second.state
+                  << ", OpenJDK: cancel after done returns false)"
+                  << std::endl;
+        return false;
+    }
+    it->second.state = kFutureCancelled;
+    // Token law: the queued task rides token == future oid; removing the
+    // token entry BEFORE dispatch means the task NEVER runs (OpenJDK
+    // cancel-true ⇒ NO_LONGER_RUNNING).
+    if (registry_) {
+        if (auto* hs = registry_->find_as<HandlerShadow>()) {
+            size_t removed = hs->remove_by_token(future_oid);
+            std::cerr << "[EXECUTOR][FUTURE] cancel o" << future_oid
+                      << " -> true (removed " << removed
+                      << " queued entr" << (removed == 1 ? "y" : "ies")
+                      << " by token)" << std::endl;
+        }
+    }
+    future_of_task_.erase(it->second.task_oid);
+    return true;
+}
