+int64_t LocksShadow::phaser_register(uint32_t oid) {
+    PhaserState& st = phaser_states_[oid];
+    if (st.terminated) return st.phase | (1L << 63); // JDK TERMINAL marker
+    st.registered++;
+    return st.phase;
+}
+int64_t LocksShadow::phaser_arrive(uint32_t oid) {
+    PhaserState& st = phaser_states_[oid];
+    if (st.terminated) return st.phase | (1L << 63);
+    int64_t arrival_phase = st.phase;
+    st.arrived++;
+    if (st.arrived >= st.registered) {
+        // Advancing arrival: release EVERY waiter of this generation (the
+        // engine re-checks the phase at re-entry — a phase change IS the
+        // advance), then open the next generation.
+        if (registry_) {
+            if (auto* ts = registry_->find_as<ThreadShadow>()) {
+                size_t woken = ts->notify_monitor(oid, /*all=*/true);
+                (void)woken;
+            }
+        }
+        st.phase++;
+        st.arrived = 0;
+        // JDK default onAdvance: terminate when no parties remain.
+        if (st.registered == 0) st.terminated = true;
+    }
+    return arrival_phase;
+}
+int64_t LocksShadow::phaser_arrive_and_deregister(uint32_t oid) {
+    PhaserState& st = phaser_states_[oid];
+    if (st.terminated) return st.phase | (1L << 63);
+    if (st.registered > 0) st.registered--;
+    return phaser_arrive(oid);
+}
