+void LocksShadow::xfer_register_put(uint32_t oid, uint32_t item,
+                                    const std::string& desc) {
+    TransferState& st = transfer_states_[oid];
+    if (st.xfer_pending) return;  // deterministic single-slot (JDK: one
+                                  // unmatched producer per rendezvous)
