+bool LocksShadow::xfer_take(uint32_t oid, uint32_t& out_item,
+                            std::string& out_desc) {
+    TransferState& st = transfer_states_[oid];
+    if (st.xfer_pending) {
+        // The waiting producer's item is delivered FIRST (OpenJDK xfer:
+        // a consumer matches an unmatched producer before the queue).
+        out_item = st.xfer_item;
+        out_desc = st.xfer_desc;
+        st.xfer_pending = false;
+        st.xfer_item = 0;
+        st.xfer_desc.clear();
+        return true;
+    }
+    if (st.elements.empty()) return false;
+    out_item = st.elements.front();
+    out_desc = st.descs.front();
+    st.elements.pop_front();
+    st.descs.pop_front();
+    return true;
+}
+bool LocksShadow::xfer_peek(uint32_t oid, uint32_t& out_item,
+                            std::string& out_desc) const {
+    auto it = transfer_states_.find(oid);
+    if (it == transfer_states_.end()) return false;
+    if (it->second.xfer_pending) {
+        out_item = it->second.xfer_item;
+        out_desc = it->second.xfer_desc;
+        return true;
+    }
+    if (it->second.elements.empty()) return false;
+    out_item = it->second.elements.front();
+    out_desc = it->second.descs.front();
+    return true;
+}
+bool LocksShadow::xfer_enqueue(uint32_t oid, uint32_t item,
+                               const std::string& desc) {
+    TransferState& st = transfer_states_[oid];
