+size_t LocksShadow::xfer_size(uint32_t oid) const {
+    auto it = transfer_states_.find(oid);
+    if (it == transfer_states_.end()) return 0;
+    return it->second.elements.size() + (it->second.xfer_pending ? 1 : 0);
