+void LocksShadow::dq_offer(uint32_t oid, uint32_t item,
+                           const std::string& desc, int64_t due_ms) {
+    DueEntry e;
+    e.item = item;
+    e.desc = desc;
+    e.due_ms = due_ms;
+    e.seq = dq_seq_++;
+    std::vector<DueEntry>& v = due_queues_[oid];
+    // (due, seq) order — the JDK (getDelay, compareTo) tie law.
+    auto at = std::upper_bound(
+        v.begin(), v.end(), e, [](const DueEntry& a, const DueEntry& b) {
+            return a.due_ms != b.due_ms ? a.due_ms < b.due_ms
+                                        : a.seq < b.seq;
+        });
+    v.insert(at, e);
+}
+bool LocksShadow::dq_peek(uint32_t oid, uint32_t& out_item,
+                          std::string& out_desc, int64_t& out_due_ms) const {
+    auto it = due_queues_.find(oid);
+    if (it == due_queues_.end() || it->second.empty()) return false;
+    out_item = it->second.front().item;
+    out_desc = it->second.front().desc;
+    out_due_ms = it->second.front().due_ms;
+    return true;
+}
+bool LocksShadow::dq_head_due(uint32_t oid, int64_t& out_due_ms) const {
+    auto it = due_queues_.find(oid);
