+bool LocksShadow::dq_poll_due(uint32_t oid, int64_t now_ms, uint32_t& out_item,
+                              std::string& out_desc) {
+    auto it = due_queues_.find(oid);
+    if (it == due_queues_.end() || it->second.empty()) return false;
+    if (it->second.front().due_ms > now_ms) return false;  // JDK: not expired
+    out_item = it->second.front().item;
+    out_desc = it->second.front().desc;
+    it->second.erase(it->second.begin());
+    return true;
