+// TEST 83 — LinkedTransferQueue (FIX 12): FIFO storage; transfer arms the
+// rendezvous slot (producer parks); tryTransfer is immediate-false with no
+// waiting consumer; take consumes a PENDING TRANSFER before the FIFO.
+static void test83_ltq(DalvikHeap& heap, ThreadShadow* ts, HandlerShadow* hs,
+                       LocksShadow* ls) {
+    std::cout << "\n[TEST 83] LinkedTransferQueue law\n";
+    uint32_t q = heap.allocate(kLTQ, 0, 0);
+    call(ls, kLTQ, "<init>", true, q);
+    uint32_t e1 = heap.allocate(kTaskCls, 0, 0);
+    uint32_t e2 = heap.allocate(kTaskCls, 0, 0);
+    uint32_t e3 = heap.allocate(kTaskCls, 0, 0);
+    check(call(ls, kLTQ, "put", true, q, {obj_arg(e1)}).handled,
+          "put(e1) enqueues");
+    check(call(ls, kLTQ, "offer", true, q, {obj_arg(e2)}).bool_val,
+          "offer(e2) true (unbounded)");
+    check(ls->xfer_size(q) == 2, "size 2 (FIFO storage)");
+    // transfer with NO waiting consumer → pending slot (producer parks).
+    call(ls, kLTQ, "transfer", true, q, {obj_arg(e3)});
+    check(ls->xfer_has_pending(q), "transfer armed the rendezvous slot");
+    check(ls->xfer_size(q) == 3, "size counts the pending transfer");
+    CallResult tt = call(ls, kLTQ, "tryTransfer", true, q, {obj_arg(e1)});
+    check(tt.handled && tt.bool_val == false,
+          "tryTransfer with no waiting consumer → FALSE (JDK law)");
+    check(ls->xfer_size(q) == 3,
+          "the failed tryTransfer did NOT enqueue (JDK contract)");
+    // take: the PENDING TRANSFER wins over the FIFO storage.
+    CallResult t1 = call(ls, kLTQ, "take", true, q);
+    check(t1.handled && t1.object_id == e3,
+          "take consumes the pending TRANSFER first (consumer-first xfer)");
+    check(!ls->xfer_has_pending(q), "transfer slot consumed");
+    CallResult t2 = call(ls, kLTQ, "take", true, q);
+    check(t2.handled && t2.object_id == e1, "then the FIFO head (e1)");
+    CallResult t3 = call(ls, kLTQ, "poll", true, q);
+    check(t3.handled && t3.object_id == e2, "then e2 (FIFO order kept)");
+    check(ls->xfer_size(q) == 0, "queue drained");
+    CallResult npe = call(ls, kLTQ, "put", true, q, {null_arg()});
+    check(npe.is_exc && npe.exc_class == "Ljava/lang/NullPointerException;",
+          "put(null) → NPE");
+    ev(ts, hs, "TEST83 LTQ");
+}
